13	/** Resolves the plugin pipeline for a build: the configured plugins when --config is given and non-empty, otherwise the built-ins. */
14	function resolvePlugins(configOpt: string | undefined): Plugin[] {
15	  if (!configOpt) return defaultBuildPlugins();
16	  const config = loadConfig(path.resolve(process.cwd(), configOpt));
17	  return config.plugins && config.plugins.length > 0 ? config.plugins : defaultBuildPlugins();
18	}
19	
20	export function createCli(): Command {
21	  const program = new Command();
22	
23	  program
24	    .name('ssg')
25	    .description('A static site generator for Markdown content');
26	
27	  program
28	    .command('build')
29	    .description('Generate the static site')
30	    .option('--content <dir>', 'content directory to read Markdown files from', './content')
31	    .option('--output <dir>', 'output directory to write the generated site to', './dist')
32	    .option('--templates <dir>', 'templates directory containing layouts/ and partials/', './templates')
33	    .option('--config <file>', 'path to a ssg.config.ts plugin config file (defaults to the built-in plugins)')
34	    .action((opts: { content: string; output: string; templates: string; config?: string }) => {
35	      const contentDir = path.resolve(process.cwd(), opts.content);
36	      const outputDir = path.resolve(process.cwd(), opts.output);
37	      const templatesDir = path.resolve(process.cwd(), opts.templates);
38	
39	      const result = opts.config
40	        ? new SsgEngine({
41	            contentDir,
42	            outputDir,
43	            templatesDir,
44	            plugins: resolvePlugins(opts.config),
45	          }).build()
46	        : build({ contentDir, outputDir, templatesDir });
47	
48	      // eslint-disable-next-line no-console
49	      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
50	    });
51	
52	  program
53	    .command('serve')
54	    .description('Build the site, then serve it with live reload while watching for changes')
55	    .option('--content <dir>', 'content directory to read Markdown files from', './content')
56	    .option('--output <dir>', 'output directory to write the generated site to', './dist')
57	    .option('--templates <dir>', 'templates directory containing layouts/ and partials/', './templates')
58	    .option('--port <port>', 'port to serve the dev server on', '3000')
59	    .option('--config <file>', 'path to a ssg.config.ts plugin config file (defaults to the built-in plugins)')
60	    .action(
61	      async (opts: {
62	        content: string;
63	        output: string;
64	        templates: string;
65	        port: string;
66	        config?: string;
67	      }) => {
68	        const contentDir = path.resolve(process.cwd(), opts.content);
69	        const outputDir = path.resolve(process.cwd(), opts.output);
70	        const templatesDir = path.resolve(process.cwd(), opts.templates);
71	        const port = Number(opts.port);
72	
73	        const handle = opts.config
74	          ? await serveWithConfig(opts.config, { contentDir, outputDir, templatesDir, port })
75	          : await serve({ contentDir, outputDir, templatesDir, port });
76	
77	        // eslint-disable-next-line no-console
78	        console.log(`Dev server running at ${handle.url}`);
79	        // eslint-disable-next-line no-console
80	        console.log(`Watching ${opts.content} and ${opts.templates} for changes...`);
81	      }
82	    );
83	
84	  return program;
85	}
