87	async function serveWithConfig(
88	  configOpt: string,
89	  dirs: { contentDir: string; outputDir: string; templatesDir: string; port: number }
90	) {
91	  const plugins = resolvePlugins(configOpt);
92	  let devServer = plugins.find(
93	    (plugin): plugin is DevServerPlugin => plugin instanceof DevServerPlugin
94	  );
95	  if (!devServer) {
96	    devServer = new DevServerPlugin();
97	    plugins.push(devServer);
98	  }
99	
100	  const engine = new SsgEngine({
101	    contentDir: dirs.contentDir,
102	    outputDir: dirs.outputDir,
103	    templatesDir: dirs.templatesDir,
104	    plugins,
105	  });
106	  engine.build();
107	
108	  return devServer.start({
109	    outputDir: dirs.outputDir,
110	    watchPaths: [dirs.contentDir, dirs.templatesDir],
111	    port: dirs.port,
112	    debounceMs: DEFAULT_SERVE_DEBOUNCE_MS,
113	    rebuild: () => {
114	      engine.build();
115	    },
116	  });
117	}
118	
119	export function run(argv: string[]): void {
120	  createCli().parse(argv);
121	}
122	
123	if (require.main === module) {
124	  run(process.argv);
125	}
