1	import * as fs from 'fs';
2	import * as path from 'path';
3	import type { Plugin, PluginContext, PluginConfig } from './plugin';
4	import type { Page } from './types';
5	
6	export interface EngineOptions {
7	  contentDir: string;
8	  outputDir: string;
9	  templatesDir: string;
10	  plugins: Plugin[];
11	  config?: PluginConfig;
12	}
13	
14	export interface EngineResult {
15	  pages: Page[];
16	  outputDir: string;
17	}
18	
19	/**
20	 * Core SSG engine: discovers Markdown files under `contentDir` and drives
21	 * them through the registered plugins' lifecycle hooks. The engine itself
22	 * knows nothing about Markdown parsing, templating, or serving -- those
23	 * behaviors come entirely from the plugins passed in.
24	 */
25	export class SsgEngine {
26	  constructor(private readonly options: EngineOptions) {}
27	
28	  build(): EngineResult {
29	    const { contentDir, outputDir, templatesDir, plugins } = this.options;
30	
31	    if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
32	      throw new Error(`Content directory not found: ${contentDir}`);
33	    }
34	
35	    const ctx: PluginContext = {
36	      contentDir,
37	      outputDir,
38	      templatesDir,
39	      config: this.options.config ?? {},
40	    };
41	
42	    for (const plugin of plugins) plugin.onStart?.(ctx);
43	    for (const plugin of plugins) plugin.beforeBuild?.(ctx);
44	
45	    const files = findMarkdownFiles(contentDir);
46	    const pages = files.map((filePath) => this.buildPage(filePath, contentDir, ctx));
47	    pages.sort(comparePages);
48	
49	    for (const plugin of plugins) plugin.afterBuild?.(pages, ctx);
50	    for (const plugin of plugins) plugin.onEnd?.(ctx);
51	
52	    return { pages, outputDir };
53	  }
54	
55	  private buildPage(filePath: string, contentDir: string, ctx: PluginContext): Page {
56	    let page = createPageSkeleton(filePath, contentDir);
57	    for (const plugin of this.options.plugins) {
58	      const result = plugin.onFile?.(page, ctx);
59	      if (result) page = result;
60	    }
61	    return page;
62	  }
63	}
64	
65	function createPageSkeleton(filePath: string, contentDir: string): Page {
66	  const relativePath = path.relative(contentDir, filePath);
67	  const slug = slugify(relativePath);
68	
69	  return {
70	    slug,
71	    title: slug,
72	    tags: [],
73	    html: '',
74	    sourcePath: relativePath,
75	    outputFile: `${slug}.html`,
76	  };
77	}
78	
79	function comparePages(a: Page, b: Page): number {
80	  if (a.date && b.date) return b.date.localeCompare(a.date);
81	  if (a.date) return -1;
82	  if (b.date) return 1;
83	  return a.title.localeCompare(b.title);
84	}
85	
86	function findMarkdownFiles(dir: string): string[] {
87	  const entries = fs.readdirSync(dir, { withFileTypes: true });
88	  const files: string[] = [];
89	
90	  for (const entry of entries) {
91	    const fullPath = path.join(dir, entry.name);
92	    if (entry.isDirectory()) {
93	      files.push(...findMarkdownFiles(fullPath));
94	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
95	      files.push(fullPath);
96	    }
97	  }
98	
99	  return files;
100	}
101	
102	function slugify(relativePath: string): string {
103	  const withoutExt = relativePath.replace(/\.md$/i, '');
104	  const slug = withoutExt
105	    .split(path.sep)
106	    .join('-')
107	    .toLowerCase()
108	    .replace(/[^a-z0-9-]+/g, '-')
109	    .replace(/-+/g, '-')
110	    .replace(/^-|-$/g, '');
111	
112	  // "index" is reserved for the generated listing page.
113	  if (!slug || slug === 'index') return slug === 'index' ? 'index-page' : 'page';
114	  return slug;
115	}
