1	export interface Page {
2	  /** URL-safe identifier derived from the source file path, used as the output file name. */
3	  slug: string;
4	  title: string;
5	  date?: string;
6	  tags: string[];
7	  /** Rendered HTML body (without the surrounding page template). */
8	  html: string;
9	  /** Path to the source Markdown file, relative to the content directory. */
10	  sourcePath: string;
11	  outputFile: string;
12	  /** Name of the layout template (from templates/layouts/) to render this page with, from frontmatter. Falls back to the default layout when omitted. */
13	  layout?: string;
