1	import * as fs from 'fs';
2	import type { Plugin } from './plugin';
3	
4	export interface SsgConfig {
5	  plugins?: Plugin[];
6	}
7	
8	let tsLoaderRegistered = false;
9	
10	/**
11	 * Registers ts-node so plain `require()` can load a raw .ts config file when
12	 * running outside a TypeScript-aware host (e.g. the compiled CLI). Under a
13	 * host that already understands .ts files (such as ts-jest during tests),
14	 * this is a harmless no-op.
15	 */
16	function ensureTypeScriptLoader(): void {
17	  if (tsLoaderRegistered) return;
18	  tsLoaderRegistered = true;
19	  try {
20	    // eslint-disable-next-line @typescript-eslint/no-var-requires
21	    require('ts-node/register');
22	  } catch {
23	    // The current runtime may already be able to load .ts files without it.
24	  }
25	}
26	
27	/**
28	 * Loads plugin configuration from an `ssg.config.ts` (or .js) file at
29	 * `configPath`. Returns an empty config when the file does not exist, so
30	 * callers can fall back to their own built-in defaults.
31	 */
32	export function loadConfig(configPath: string): SsgConfig {
33	  if (!fs.existsSync(configPath)) {
34	    return {};
35	  }
36	
37	  if (configPath.endsWith('.ts')) {
38	    ensureTypeScriptLoader();
39	  }
40	
41	  const resolved = require.resolve(configPath);
42	  delete require.cache[resolved];
43	  // eslint-disable-next-line @typescript-eslint/no-var-requires
44	  const loaded = require(resolved);
45	  const config: SsgConfig = loaded?.default ?? loaded;
46	  return config ?? {};
47	}
