1	import matter from 'gray-matter';
2	
3	export interface FrontmatterData {
4	  title?: string;
5	  date?: string;
6	  tags?: string[];
7	  [key: string]: unknown;
8	}
9	
10	export interface ParsedMarkdown {
11	  data: FrontmatterData;
12	  content: string;
13	}
14	
15	/**
16	 * gray-matter only parses JSON frontmatter out of the box, so the raw
17	 * `---`-delimited YAML block is extracted here and parsed with a simple
18	 * key: value splitter, then merged on top of gray-matter's own output.
19	 */
20	export function parseFrontmatter(raw: string): ParsedMarkdown {
21	  const gm = matter(raw);
22	  const { block } = extractFrontmatterBlock(raw);
23	  const yamlData = parseSimpleYaml(block);
24	  const data: FrontmatterData = { ...gm.data, ...yamlData };
25	
26	  if (typeof data.tags === 'string') {
27	    data.tags = splitList(data.tags);
28	  }
29	
30	  return { data, content: gm.content };
31	}
32	
33	function extractFrontmatterBlock(raw: string): { block: string; content: string } {
34	  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
35	  if (!match) {
36	    return { block: '', content: raw };
37	  }
38	  return { block: match[1], content: match[2] };
39	}
40	
41	function parseSimpleYaml(block: string): Record<string, unknown> {
42	  const data: Record<string, unknown> = {};
43	  const lines = block.split(/\r?\n/);
44	
45	  for (const line of lines) {
46	    const trimmed = line.trim();
47	    if (!trimmed || trimmed.startsWith('#')) continue;
48	
49	    const separatorIndex = trimmed.indexOf(':');
50	    if (separatorIndex === -1) continue;
51	
52	    const key = trimmed.slice(0, separatorIndex).trim();
53	    const rawValue = trimmed.slice(separatorIndex + 1).trim();
54	    if (!key) continue;
55	
56	    data[key] = parseValue(rawValue);
57	  }
58	
59	  return data;
60	}
61	
62	function parseValue(value: string): unknown {
63	  if (value.startsWith('[') && value.endsWith(']')) {
64	    return splitList(value.slice(1, -1));
65	  }
66	  return stripQuotes(value);
67	}
68	
69	function splitList(value: string): string[] {
70	  return value
71	    .split(',')
72	    .map((item) => stripQuotes(item.trim()))
73	    .filter((item) => item.length > 0);
74	}
75	
76	function stripQuotes(value: string): string {
77	  if (value.length >= 2) {
78	    const first = value[0];
79	    const last = value[value.length - 1];
80	    if ((first === '"' && last === '"') || (first === "'" && last === "'")) {
81	      return value.slice(1, -1);
82	    }
83	  }
84	  return value;
85	}
