1	import type { Page } from './types';
2	
3	/** Arbitrary settings a plugin author can read off `PluginContext.config`. */
4	export interface PluginConfig {
5	  [key: string]: unknown;
6	}
7	
8	/** Shared, read-only build context passed to every lifecycle hook. */
9	export interface PluginContext {
10	  contentDir: string;
11	  outputDir: string;
12	  templatesDir: string;
13	  config: PluginConfig;
14	}
15	
16	/**
17	 * A plugin participates in the build by implementing any subset of these
18	 * lifecycle hooks. The core engine runs every plugin's implementation of a
19	 * given hook, in plugin registration order, before moving on to the next
20	 * hook in the pipeline:
21	 *
22	 *   onStart -> beforeBuild -> onFile (per discovered page) -> afterBuild -> onEnd
23	 *
24	 * Hooks are synchronous so a single build() call can stay synchronous end to
25	 * end, matching this SSG's existing (pre-plugin) API.
26	 */
27	export interface Plugin {
28	  name: string;
29	  /** Runs once, before the content directory is even validated. */
30	  onStart?(ctx: PluginContext): void;
31	  /** Runs once per build, after validation and before any file is processed. */
32	  beforeBuild?(ctx: PluginContext): void;
33	  /**
34	   * Runs once per discovered page, threading the page through every plugin
35	   * in order. Return an updated page to replace it for the remaining
36	   * plugins; returning nothing leaves the page as-is.
37	   */
38	  onFile?(page: Page, ctx: PluginContext): Page | void;
39	  /** Runs once per build, after every page has been processed. */
40	  afterBuild?(pages: Page[], ctx: PluginContext): void;
41	  /** Runs once per build, after afterBuild. */
42	  onEnd?(ctx: PluginContext): void;
43	}
