1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseFrontmatter } from '../src/frontmatter';
4	import { renderMarkdown } from '../src/render';
5	import type { Plugin, PluginContext } from '../src/plugin';
6	import type { Page } from '../src/types';
7	
8	/**
9	 * Built-in plugin that turns each discovered Markdown file into a page:
10	 * parses its frontmatter, renders the Markdown body to HTML, and fills in
11	 * title/date/tags/layout metadata (falling back to the slug-derived title
12	 * when frontmatter omits one).
13	 */
14	export class MarkdownPlugin implements Plugin {
15	  readonly name = 'markdown';
16	
17	  onFile(page: Page, ctx: PluginContext): Page {
18	    const filePath = path.join(ctx.contentDir, page.sourcePath);
19	    const raw = fs.readFileSync(filePath, 'utf8');
20	    const { data, content } = parseFrontmatter(raw);
21	    const html = renderMarkdown(content);
22	
23	    const title = typeof data.title === 'string' && data.title.trim() ? data.title : page.slug;
24	    const date = typeof data.date === 'string' && data.date.trim() ? data.date : undefined;
25	    const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
26	    const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout.trim() : undefined;
27	
28	    return { ...page, title, date, tags, html, layout };
29	  }
30	}
