1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { TemplateEngine } from '../src/templates';
4	import { renderIndexBodyHtml } from '../src/render';
5	import type { Plugin, PluginContext } from '../src/plugin';
6	import type { Page } from '../src/types';
7	
8	const INDEX_LAYOUT_NAME = 'index';
9	
10	/**
11	 * Built-in plugin that renders every page through its Handlebars layout and
12	 * writes the resulting HTML files, then generates and writes the `index.html`
13	 * listing page once all pages are known.
14	 */
15	export class TemplatePlugin implements Plugin {
16	  readonly name = 'template';
17	
18	  private engine?: TemplateEngine;
19	
20	  beforeBuild(ctx: PluginContext): void {
21	    this.engine = new TemplateEngine(ctx.templatesDir);
22	  }
23	
24	  afterBuild(pages: Page[], ctx: PluginContext): void {
25	    const engine = this.requireEngine();
26	
27	    fs.mkdirSync(ctx.outputDir, { recursive: true });
28	
29	    for (const page of pages) {
30	      const outPath = path.join(ctx.outputDir, page.outputFile);
31	      fs.mkdirSync(path.dirname(outPath), { recursive: true });
32	      const html = engine.render(page.layout, {
33	        title: page.title,
34	        date: page.date,
35	        tags: page.tags,
36	        body: page.html,
37	      });
38	      fs.writeFileSync(outPath, html, 'utf8');
39	    }
40	
41	    const indexLayout = engine.hasLayout(INDEX_LAYOUT_NAME) ? INDEX_LAYOUT_NAME : undefined;
42	    const indexHtml = engine.render(indexLayout, {
43	      title: 'All Pages',
44	      tags: [],
45	      body: renderIndexBodyHtml(pages),
46	    });
47	    fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), indexHtml, 'utf8');
48	  }
49	
50	  private requireEngine(): TemplateEngine {
51	    if (!this.engine) {
52	      throw new Error('TemplatePlugin: beforeBuild must run before afterBuild');
53	    }
54	    return this.engine;
55	  }
56	}
