1	import * as fs from 'fs';
2	import * as path from 'path';
3	import Handlebars from 'handlebars';
4	
5	export const DEFAULT_LAYOUT_NAME = 'default';
6	
7	export interface RenderContext {
8	  title: string;
9	  date?: string;
10	  tags: string[];
11	  body: string;
12	}
13	
14	/**
15	 * Compiles Handlebars layout templates and registers partials, so pages can
16	 * be wrapped in a layout selected via frontmatter (falling back to the
17	 * `default` layout when none is specified).
18	 */
19	export class TemplateEngine {
20	  private readonly handlebars: typeof Handlebars;
21	  private readonly layouts = new Map<string, HandlebarsTemplateDelegate>();
22	
23	  constructor(private readonly templatesDir: string) {
24	    this.handlebars = Handlebars.create();
25	
26	    if (!fs.existsSync(templatesDir) || !fs.statSync(templatesDir).isDirectory()) {
27	      throw new Error(`Templates directory not found: ${templatesDir}`);
28	    }
29	
30	    this.registerPartials();
31	    this.loadLayouts();
32	
33	    if (!this.layouts.has(DEFAULT_LAYOUT_NAME)) {
34	      throw new Error(
35	        `Default layout "${DEFAULT_LAYOUT_NAME}.hbs" not found in ${this.layoutsDir}`
36	      );
37	    }
38	  }
39	
40	  private get partialsDir(): string {
41	    return path.join(this.templatesDir, 'partials');
42	  }
43	
44	  private get layoutsDir(): string {
45	    return path.join(this.templatesDir, 'layouts');
46	  }
47	
48	  private registerPartials(): void {
49	    if (!fs.existsSync(this.partialsDir)) return;
50	
51	    for (const file of listTemplateFiles(this.partialsDir)) {
52	      const name = path.basename(file, '.hbs');
53	      const source = fs.readFileSync(path.join(this.partialsDir, file), 'utf8');
54	      this.handlebars.registerPartial(name, source);
55	    }
56	  }
57	
58	  private loadLayouts(): void {
59	    if (!fs.existsSync(this.layoutsDir)) {
60	      throw new Error(`Layouts directory not found: ${this.layoutsDir}`);
61	    }
62	
63	    for (const file of listTemplateFiles(this.layoutsDir)) {
64	      const name = path.basename(file, '.hbs');
65	      const source = fs.readFileSync(path.join(this.layoutsDir, file), 'utf8');
66	      this.layouts.set(name, this.handlebars.compile(source));
67	    }
68	  }
69	
70	  hasLayout(name: string): boolean {
71	    return this.layouts.has(name);
72	  }
73	
74	  render(layoutName: string | undefined, context: RenderContext): string {
75	    const name = layoutName && layoutName.trim() ? layoutName.trim() : DEFAULT_LAYOUT_NAME;
76	    const layout = this.layouts.get(name);
77	
78	    if (!layout) {
79	      throw new Error(`Template layout "${name}" not found in ${this.layoutsDir}`);
80	    }
81	
82	    return layout(context);
83	  }
84	}
85	
86	function listTemplateFiles(dir: string): string[] {
87	  return fs
88	    .readdirSync(dir, { withFileTypes: true })
89	    .filter((entry) => entry.isFile() && /\.hbs$/i.test(entry.name))
90	    .map((entry) => entry.name);
91	}
