9	export interface DevServerStartOptions {
10	  outputDir: string;
11	  /** Directories to watch; a change in any of them triggers a rebuild. */
12	  watchPaths: string[];
13	  /** Port to listen on. Use 0 to let the OS assign an ephemeral port. */
14	  port: number;
15	  /** Delay (ms) between a watched file change and the triggered rebuild, to coalesce bursts of changes. */
16	  debounceMs: number;
17	  /** Invoked to rebuild the site; the resulting pages flow back through this plugin's afterBuild hook. */
18	  rebuild: () => void;
19	}
