21	export interface DevServerHandle {
22	  port: number;
23	  url: string;
24	  close(): Promise<void>;
25	}
26	
27	const LIVERELOAD_PATH = '/__livereload';
28	
29	const MIME_TYPES: Record<string, string> = {
30	  '.html': 'text/html; charset=utf-8',
31	  '.css': 'text/css; charset=utf-8',
32	  '.js': 'text/javascript; charset=utf-8',
33	  '.json': 'application/json; charset=utf-8',
34	  '.svg': 'image/svg+xml',
35	  '.png': 'image/png',
36	  '.jpg': 'image/jpeg',
37	  '.jpeg': 'image/jpeg',
38	  '.gif': 'image/gif',
39	  '.ico': 'image/x-icon',
40	  '.txt': 'text/plain; charset=utf-8',
41	  '.xml': 'application/xml; charset=utf-8',
42	};
43	
44	function liveReloadScript(): string {
45	  return `<script>
46	(function () {
47	  var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
48	  var socket = new WebSocket(protocol + '//' + window.location.host + '${LIVERELOAD_PATH}');
49	  socket.addEventListener('message', function (event) {
50	    if (event.data === 'reload') {
51	      window.location.reload();
52	    }
53	  });
54	})();
55	</script>`;
56	}
57	
58	function injectLiveReload(html: string): string {
59	  const script = liveReloadScript();
60	  if (/<\/body>/i.test(html)) {
61	    return html.replace(/<\/body>/i, `${script}\n</body>`);
62	  }
63	  return `${html}\n${script}`;
64	}
65	
66	/** Resolves a request path to a file within rootDir, refusing to escape it via `..` traversal. */
67	function resolveServablePath(rootDir: string, urlPath: string): string | undefined {
68	  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
69	  let filePath = path.normalize(path.join(rootDir, decoded));
70	
71	  if (filePath !== rootDir && !filePath.startsWith(rootDir + path.sep)) {
72	    return undefined;
73	  }
74	
75	  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
76	    filePath = path.join(filePath, 'index.html');
77	  }
78	
79	  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
80	    return undefined;
81	  }
82	
83	  return filePath;
84	}
