86	/**
87	 * Built-in plugin that serves the built site over HTTP with live reload.
88	 * As a `Plugin`, its `afterBuild` hook broadcasts a reload message to
89	 * connected browsers whenever a rebuild completes as part of the plugin
90	 * pipeline. The HTTP server, WebSocket server, and file watcher themselves
91	 * are a long-lived process spanning many rebuilds, so they're managed via
92	 * the dedicated `start()`/`close()` API below rather than the single-shot
93	 * `onStart`/`onEnd` hooks.
94	 */
95	export class DevServerPlugin implements Plugin {
96	  readonly name = 'dev-server';
97	
98	  private readonly clients = new Set<WebSocket>();
99	
100	  afterBuild(_pages: Page[], _ctx: PluginContext): void {
101	    this.broadcastReload();
102	  }
103	
104	  private broadcastReload(): void {
105	    for (const client of this.clients) {
106	      if (client.readyState === WebSocket.OPEN) {
107	        client.send('reload');
108	      }
109	    }
110	  }
111	
112	  private requestListener(outputDir: string): http.RequestListener {
113	    return (req, res) => {
114	      const filePath = resolveServablePath(outputDir, req.url ?? '/');
115	
116	      if (!filePath) {
117	        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
118	        res.end('Not found');
119	        return;
120	      }
121	
122	      const ext = path.extname(filePath).toLowerCase();
123	      const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
124	
125	      if (ext === '.html') {
126	        const html = fs.readFileSync(filePath, 'utf8');
127	        res.writeHead(200, { 'Content-Type': contentType });
128	        res.end(injectLiveReload(html));
129	        return;
130	      }
131	
132	      res.writeHead(200, { 'Content-Type': contentType });
133	      fs.createReadStream(filePath).pipe(res);
134	    };
135	  }
136	
137	  /** Starts the HTTP server, WebSocket server, and file watcher, resolving once both are ready. */
138	  start(options: DevServerStartOptions): Promise<DevServerHandle> {
139	    const { outputDir, watchPaths, port, debounceMs, rebuild } = options;
140	
141	    const wss = new WebSocketServer({ noServer: true });
142	    const httpServer = http.createServer(this.requestListener(outputDir));
143	
144	    httpServer.on('upgrade', (req, socket, head) => {
145	      if (req.url !== LIVERELOAD_PATH) {
146	        socket.destroy();
147	        return;
148	      }
149	      wss.handleUpgrade(req, socket, head, (ws) => {
150	        this.clients.add(ws);
151	        ws.on('close', () => this.clients.delete(ws));
152	      });
153	    });
154	
155	    let rebuildTimer: ReturnType<typeof setTimeout> | undefined;
156	    const scheduleRebuild = (): void => {
157	      if (rebuildTimer) clearTimeout(rebuildTimer);
158	      rebuildTimer = setTimeout(() => {
159	        rebuildTimer = undefined;
160	        try {
161	          rebuild();
162	        } catch (err) {
163	          // eslint-disable-next-line no-console
164	          console.error('Rebuild failed:', err instanceof Error ? err.message : err);
165	        }
166	      }, debounceMs);
167	    };
168	
169	    const watcher = chokidar.watch(watchPaths, { ignoreInitial: true });
170	    watcher.on('add', scheduleRebuild);
171	    watcher.on('change', scheduleRebuild);
172	    watcher.on('unlink', scheduleRebuild);
173	
174	    const watcherReady = new Promise<void>((resolve) => watcher.once('ready', resolve));
175	    const listening = new Promise<number>((resolve, reject) => {
176	      httpServer.once('error', reject);
177	      httpServer.listen(port, () => {
178	        httpServer.removeListener('error', reject);
179	        const address = httpServer.address();
180	        resolve(typeof address === 'object' && address ? address.port : port);
181	      });
182	    });
183	
184	    const clients = this.clients;
185	
186	    return Promise.all([listening, watcherReady]).then(([boundPort]) => ({
187	      port: boundPort,
188	      url: `http://localhost:${boundPort}`,
189	      close(): Promise<void> {
190	        if (rebuildTimer) clearTimeout(rebuildTimer);
191	        for (const client of clients) client.terminate();
192	        return watcher.close().then(
193	          () =>
194	            new Promise<void>((resolveClose, rejectClose) => {
195	              wss.close(() => {
196	                httpServer.close((err) => {
197	                  if (err) rejectClose(err);
198	                  else resolveClose();
199	                });
200	              });
201	            })
202	        );
203	      },
204	    }));
205	  }
206	}
