4	import { DevServerPlugin } from '../plugins/dev-server';
5	import type { BuildOptions } from './generator';
6	
7	export interface ServeOptions extends BuildOptions {
8	  /** Port to listen on. Use 0 to let the OS assign an ephemeral port. Defaults to 3000. */
9	  port?: number;
10	  /** Delay (ms) between a watched file change and the triggered rebuild, to coalesce bursts of changes. */
11	  debounceMs?: number;
12	}
13	
14	export interface ServeHandle {
15	  port: number;
16	  url: string;
