18	}
19	
20	const DEFAULT_PORT = 3000;
21	const DEFAULT_DEBOUNCE_MS = 100;
22	
23	/**
24	 * Starts a dev server that serves the built site from `outputDir`, rebuilds
25	 * whenever `contentDir` or `templatesDir` change, and pushes a live-reload
26	 * notification over WebSocket to connected pages so browsers refresh
27	 * automatically once the rebuild completes.
28	 */
29	export function serve(options: ServeOptions): Promise<ServeHandle> {
30	  const { contentDir, outputDir } = options;
31	  const templatesDir = options.templatesDir ?? path.resolve(process.cwd(), 'templates');
32	  const debounceMs = options.debounceMs ?? DEFAULT_DEBOUNCE_MS;
33	
34	  const devServer = new DevServerPlugin();
35	  const engine = new SsgEngine({
36	    contentDir,
37	    outputDir,
38	    templatesDir,
39	    plugins: [...defaultBuildPlugins(), devServer],
40	  });
41	
42	  engine.build();
43	
44	  return devServer.start({
45	    outputDir,
46	    watchPaths: [contentDir, templatesDir],
47	    port: options.port ?? DEFAULT_PORT,
48	    debounceMs,
49	    rebuild: () => {
50	      engine.build();
51	    },
52	  });
53	}
